data.value:
SELECT TOP 20 AUTO_NUMBER, DATE, TIME, LAST_NAME, FIRST_NAME, EMAIL, COMPANY
FROM CONTACT
ORDER BY AUTO_NUMBER DESC;

SELECT TOP 20 AUTO_NUMBER, DATE, EMAIL
FROM SUBSCRIBE
ORDER BY AUTO_NUMBER DESC;

SELECT TOP 50 AUTO_NUMBER, DATE, TIME, IP_ADDRESS, USER_NAME, ACTION
FROM LOGIN
ORDER BY AUTO_NUMBER DESC;

SELECT USER_NAME, FIRST_NAME, LAST_NAME, TotpEnabled
FROM USERS
ORDER BY USER_NAME;

-- A user lost their phone AND their recovery codes: replace name with their user name.
-- (Another administrator can also do it from the "Users" page.)
UPDATE USERS SET TotpSecret = NULL, TotpEnabled = 0, TotpLastStep = NULL, TotpRecovery = NULL WHERE USER_NAME = 'name';
